mapper.select:
select x.ym, x.item_id, x.kind, x.unit_cd, x.source, trim_scale(sum(x.qty)) as qty
  from (
        select to_char(r.occurred_at at time zone #{zone}, 'YYYY-MM') as ym, w.item_id, d.kind, r.unit_cd, 'RESULT' as source, d.qty
          from prd_result r
          join prd_result_defect d on d.result_id = r.result_id
          join prd_wo w on w.wo_id = r.wo_id
         where r.occurred_at >= #{start} and r.occurred_at < #{end}
           and w.plant_cd = #{plantCd}
        union all
        select to_char(k.occurred_at at time zone #{zone}, 'YYYY-MM'), w.item_id, 'SCRAP', k.unit_cd, 'REWORK', k.scrap_qty
          from prd_rework k
          join prd_wo w on w.wo_id = k.wo_id
         where k.scrap_qty <> 0
           and k.occurred_at >= #{start} and k.occurred_at < #{end}
           and w.plant_cd = #{plantCd}
       ) x
 group by x.ym, x.item_id, x.kind, x.unit_cd, x.source
having sum(x.qty) <> 0
 order by x.ym, x.item_id, x.source, x.kind, x.unit_cd
